eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   HOUSE_TOPICS: () => (/* binding */ HOUSE_TOPICS)\n/* harmony export */ });\nconst HOUSE_DEFINITIONS = [\n    {\n        id: 'house-1',\n        house: 1,\n        aliases: {\n            ru: [\n                'первый дом',\n                '1 дом'\n            ],\n            en: [\n                'first house',\n                '1st house',\n                'house 1'\n            ]\n        },\n        keywords: {\n            ru: [\n                'асцендент',\n                'первое впечатление',\n                'начало',\n                'манера'\n            ],\n            en: [\n                'ascendant',\n                'first impression',\n                'beginning',\n                'manner'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Первый дом',\n                summary: 'Первый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают начало действий, внешнюю манеру и первое впечатление.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К первому дому относят поведение в новой обстановке, способ показать себя и первую заметную реакцию на происходящее. Он не описывает весь характер или внешность человека.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Первый дом начинается с Асцендента, точки круга карты на восточном горизонте в момент рождения. При чтении учитывают знак зодиака, в котором находится Асцендент, планеты внутри дома и их аспекты с другими планетами и точками карты.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Первый дом используют для чтения первого впечатления, начала действий и поведения в новой обстановке; весь характер человека он не описывает.'\n            },\n            en: {\n                title: 'First house',\n                summary: 'The first house is associated with beginnings, outward manner, and first impressions.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It describes how a person enters a new situation, makes their presence known, and responds to the immediate environment.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The first house begins at the Ascendant. Its sign, planets in the house, and aspects to the Ascendant are read together.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The first house is about how a person begins, presents themselves, and meets the outside world.'\n            }\n        }\n    },\n    {\n        id: 'house-2',\n        house: 2,\n        aliases: {\n            ru: [\n                'второй дом',\n                '2 дом'\n            ],\n            en: [\n                'second house',\n                '2nd house',\n                'house 2'\n            ]\n        },\n        keywords: {\n            ru: [\n                'деньги',\n                'имущество',\n                'навыки',\n                'личное'\n            ],\n            en: [\n                'money',\n                'possessions',\n                'skills',\n                'personal'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Второй дом',\n                summary: 'Второй дом — одна из двенадцати частей круга натальной карты. По нему рассматривают личные деньги, имущество и практические навыки.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'Ко второму дому относят обращение с собственными деньгами и вещами, способы поддерживать материальную устойчивость и навыки, которые можно применять на практике. Дом не показывает точную сумму дохода.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается второй дом, описывает подход к этим вопросам. Планеты внутри дома добавляют свои значения, а аспекты связывают их с другими планетами карты.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Второй дом используют для чтения вопросов о личных деньгах, имуществе и навыках с практической ценностью; точный доход он не предсказывает.'\n            },\n            en: {\n                title: 'Second house',\n                summary: 'The second house is associated with personal means, possessions, and what a person can maintain.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes attitudes toward money and belongings, ways of maintaining material stability, and skills with practical value.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The second house does not promise a specific income. It describes a familiar approach to personal means together with its sign, planets, and aspects.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The second house is about personal means, possessions, and practical skills.'\n            }\n        }\n    },\n    {\n        id: 'house-3',\n        house: 3,\n        aliases: {\n            ru: [\n                'третий дом',\n                '3 дом'\n            ],\n            en: [\n                'third house',\n                '3rd house',\n                'house 3'\n            ]\n        },\n        keywords: {\n            ru: [\n                'общение',\n                'обучение',\n                'соседи',\n                'братья и сёстры'\n            ],\n            en: [\n                'communication',\n                'learning',\n                'neighbors',\n                'siblings'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Третий дом',\n                summary: 'Третий дом — одна из двенадцати частей круга натальной карты. По нему рассматривают повседневное общение, начальное обучение и ближайшее окружение.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К третьему дому относят речь и обмен сведениями, школьное обучение, короткие поездки, соседей, братьев и сестёр. Это круг регулярных контактов и знакомых маршрутов, а не дальних путешествий.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается третий дом, описывает способ задавать вопросы и передавать сведения. Планеты внутри дома и их аспекты с другими планетами добавляют детали.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Третий дом используют для чтения повседневного общения, начального обучения, коротких поездок и связей с ближайшим окружением.'\n            },\n            en: {\n                title: 'Third house',\n                summary: 'The third house is associated with everyday communication, learning, and the nearby environment.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes speech and information exchange, short journeys, basic learning, neighbors, and siblings.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The sign and planets in the third house refine how a person asks questions, shares information, and moves through familiar surroundings.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The third house is about everyday information, learning, and the nearby environment.'\n            }\n        }\n    },\n    {\n        id: 'house-4',\n        house: 4,\n        aliases: {\n            ru: [\n                'четвёртый дом',\n                'четвертый дом',\n                '4 дом'\n            ],\n            en: [\n                'fourth house',\n                '4th house',\n                'house 4'\n            ]\n        },\n        keywords: {\n            ru: [\n                'дом',\n                'семья',\n                'происхождение',\n                'частная жизнь'\n            ],\n            en: [\n                'home',\n                'family',\n                'origins',\n                'private life'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Четвёртый дом',\n                summary: 'Четвёртый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают дом, семейную среду, происхождение и частную жизнь.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К четвёртому дому относят домашнюю обстановку, семейные связи, место происхождения и ту часть жизни, которая не предназначена для публики. Он не восстанавливает подробную историю семьи по одной позиции.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Четвёртый дом начинается с Основания неба, или IC, нижней точки карты, расположенной напротив Середины неба. Знак зодиака на этой границе, планеты внутри дома и их аспекты с другими планетами уточняют чтение домашних и семейных вопросов.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Четвёртый дом используют для чтения вопросов о доме, семейной среде, происхождении и частной жизни.'\n            },\n            en: {\n                title: 'Fourth house',\n                summary: 'The fourth house is associated with home, family, origins, and private life.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes the home environment, family history, connection with one’s place of origin, and what a person keeps outside public view.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The fourth house begins at the IC. Its sign and planets refine the picture of private space and family ties.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The fourth house is about home, origins, family, and private life.'\n            }\n        }\n    },\n    {\n        id: 'house-5',\n        house: 5,\n        aliases: {\n            ru: [\n                'пятый дом',\n                '5 дом'\n            ],\n            en: [\n                'fifth house',\n                '5th house',\n                'house 5'\n            ]\n        },\n        keywords: {\n            ru: [\n                'творчество',\n                'игра',\n                'романтика',\n                'дети'\n            ],\n            en: [\n                'creativity',\n                'play',\n                'romance',\n                'children'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Пятый дом',\n                summary: 'Пятый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают творчество, игру, романтический интерес и тему детей.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К пятому дому относят занятия, в которых человек создаёт что-то своё, играет, выступает перед другими или показывает романтическую симпатию. Тема детей здесь касается отношения к родительству и взаимодействия с детьми, а не предсказания их количества.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается пятый дом, описывает, как человек выражает интерес и творческую инициативу. Планеты внутри дома и аспекты, то есть их связи с другими точками карты, добавляют к этим вопросам свои значения.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Пятый дом используют для чтения вопросов о творчестве, игре, романтическом интересе и отношении к теме детей.'\n            },\n            en: {\n                title: 'Fifth house',\n                summary: 'The fifth house is associated with creativity, play, romance, and children.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It describes activities in which a person creates something of their own, enjoys the process, and allows freer expression.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'Planets and the sign of the fifth house refine the form of creativity and the approach to play, attention, romance, and children.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The fifth house is about creativity, play, romance, and personal authorship.'\n            }\n        }\n    },\n    {\n        id: 'house-6',\n        house: 6,\n        aliases: {\n            ru: [\n                'шестой дом',\n                '6 дом'\n            ],\n            en: [\n                'sixth house',\n                '6th house',\n                'house 6'\n            ]\n        },\n        keywords: {\n            ru: [\n                'распорядок',\n                'работа',\n                'обязанности',\n                'здоровье'\n            ],\n            en: [\n                'routine',\n                'work',\n                'duties',\n                'health'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Шестой дом',\n                summary: 'Шестой дом — одна из двенадцати частей круга натальной карты. По нему рассматривают распорядок, повседневную работу, обязанности и привычки ухода за телом.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К шестому дому относят повторяющиеся дела, рабочие навыки, распределение обязанностей, режим и повседневный уход за собой. Он описывает организацию быта и труда, но не ставит диагноз и не заменяет медицинскую оценку.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается шестой дом, описывает подход к регулярным задачам. Планеты внутри дома и их аспекты с другими планетами уточняют, какие вопросы чаще входят в распорядок и рабочие обязанности.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Шестой дом используют для чтения распорядка, повседневной работы, обязанностей и привычек ухода за собой; медицинских выводов он не даёт.'\n            },\n            en: {\n                title: 'Sixth house',\n                summary: 'The sixth house is associated with routine, daily work, duties, and care for the body.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes recurring tasks, working skills, the distribution of duties, and habits connected with physical well-being.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'This house does not replace medical assessment. In a chart, it describes the organization of daily tasks and self-care.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The sixth house is about routines, work, duties, and everyday care for the body.'\n            }\n        }\n    },\n    {\n        id: 'house-7',\n        house: 7,\n        aliases: {\n            ru: [\n                'седьмой дом',\n                '7 дом'\n            ],\n            en: [\n                'seventh house',\n                '7th house',\n                'house 7'\n            ]\n        },\n        keywords: {\n            ru: [\n                'партнёрство',\n                'любовь',\n                'брак',\n                'договор',\n                'другой человек'\n            ],\n            en: [\n                'partnership',\n                'love',\n                'marriage',\n                'contract',\n                'other person'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Седьмой дом',\n                summary: 'Седьмой дом — одна из двенадцати частей круга натальной карты. По нему рассматривают партнёрство, договоры и отношения между двумя равными сторонами.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К седьмому дому относят близкие и деловые союзы, брак, договоры и открытое взаимодействие с другим человеком. Речь идёт о связи один на один, где у каждой стороны есть свои интересы и обязательства.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Начало седьмого дома называют точкой «Десцендент». Она находится на западном горизонте карты напротив Асцендента. Знак зодиака на этой границе, планеты внутри дома и их аспекты с другими планетами уточняют чтение партнёрства, но не гарантируют исход отношений.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Седьмой дом используют для чтения партнёрства, договоров и прямого взаимодействия с другим человеком; исход отношений он не предсказывает.'\n            },\n            en: {\n                title: 'Seventh house',\n                summary: 'The seventh house is associated with partnership, contracts, and one-to-one relationships.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes close and business partnerships, marriage, contractual relationships, and situations that require an equal counterpart.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The seventh house begins at the Descendant. Its sign, planets, and aspects describe relationship demands but do not guarantee an outcome.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The seventh house is about partnership, contracts, and direct interaction with another person.'\n            }\n        }\n    },\n    {\n        id: 'house-8',\n        house: 8,\n        aliases: {\n            ru: [\n                'восьмой дом',\n                '8 дом'\n            ],\n            en: [\n                'eighth house',\n                '8th house',\n                'house 8'\n            ]\n        },\n        keywords: {\n            ru: [\n                'общие деньги',\n                'долги',\n                'наследство',\n                'близость'\n            ],\n            en: [\n                'shared money',\n                'debts',\n                'inheritance',\n                'intimacy'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Восьмой дом',\n                summary: 'Восьмой дом — одна из двенадцати частей круга натальной карты. По нему рассматривают общие деньги, финансовые обязательства, наследство, близость и потери.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К восьмому дому относят совместные деньги, долги, налоги, наследство и доверие в близких отношениях. Общая тема этих вопросов состоит в том, что человек зависит от чужих решений, общих условий или передачи имущества.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается восьмой дом, планеты внутри него и их аспекты с другими планетами уточняют отношение к общим обязательствам и переменам условий. Этот дом не предсказывает смерть, катастрофу или обязательную беду.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Восьмой дом используют для чтения общих денег, долгов, наследства, доверия и других вопросов, где решения зависят не от одного человека.'\n            },\n            en: {\n                title: 'Eighth house',\n                summary: 'The eighth house is associated with shared means, obligations, intimacy, and major change.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes shared money, debt, taxes, inheritance, trust in close relationships, and situations that cannot be handled entirely alone.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The eighth house does not predict death or disaster. It describes dealings with shared obligations, loss, and changing conditions.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The eighth house is about shared means, trust, obligations, and major change.'\n            }\n        }\n    },\n    {\n        id: 'house-9',\n        house: 9,\n        aliases: {\n            ru: [\n                'девятый дом',\n                '9 дом'\n            ],\n            en: [\n                'ninth house',\n                '9th house',\n                'house 9'\n            ]\n        },\n        keywords: {\n            ru: [\n                'высшее образование',\n                'путешествия',\n                'мировоззрение',\n                'публикации'\n            ],\n            en: [\n                'higher education',\n                'travel',\n                'worldview',\n                'publishing'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Девятый дом',\n                summary: 'Девятый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают мировоззрение, высшее образование, дальние поездки и распространение знаний.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К девятому дому относят университетское образование, знакомство с другими странами и культурами, право, религию, издательское дело и поиск общей системы взглядов. Это не только путешествия, а вопросы, которые расширяют картину мира.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается девятый дом, описывает способ искать объяснения и проверять убеждения. Планеты внутри дома и их аспекты с другими планетами добавляют детали к вопросам обучения, поездок и публикаций.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Девятый дом используют для чтения мировоззрения, высшего образования, дальних поездок и способов передавать знания широкой аудитории.'\n            },\n            en: {\n                title: 'Ninth house',\n                summary: 'The ninth house is associated with worldview, higher education, long journeys, and publishing.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes learning that changes the larger view, encounters with other cultures, law, religion, and the distribution of ideas.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The sign and planets in the ninth house refine how a person looks for explanations, examines beliefs, and shares knowledge with a wider audience.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The ninth house is about worldview, distant horizons, and structured learning.'\n            }\n        }\n    },\n    {\n        id: 'house-10',\n        house: 10,\n        aliases: {\n            ru: [\n                'десятый дом',\n                '10 дом'\n            ],\n            en: [\n                'tenth house',\n                '10th house',\n                'house 10'\n            ]\n        },\n        keywords: {\n            ru: [\n                'карьера',\n                'общественная роль',\n                'репутация',\n                'ответственность'\n            ],\n            en: [\n                'career',\n                'public role',\n                'reputation',\n                'responsibility'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Десятый дом',\n                summary: 'Десятый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают общественную роль, карьерное направление, репутацию и видимую ответственность.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К десятому дому относят долгие профессиональные цели, отношения с руководством и общественными правилами, репутацию и результаты, которые видят другие люди. Он говорит о направлении публичной деятельности, а не назначает конкретную должность.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Десятый дом начинается с Середины неба, или MC, верхней точки карты. Знак зодиака на этой границе, планеты внутри дома и их аспекты с другими планетами уточняют чтение карьеры и общественной роли, но не определяют единственную профессию.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Десятый дом используют для чтения общественной роли, карьерного направления, репутации и ответственности; конкретную профессию он не назначает.'\n            },\n            en: {\n                title: 'Tenth house',\n                summary: 'The tenth house is associated with public role, career direction, and visible responsibility.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes long-term professional aims, relationships with rules and authority, reputation, and results visible to other people.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The tenth house begins at the MC. Its sign and planets refine an approach to public life but do not assign a single profession.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The tenth house is about public role, career, reputation, and responsibility.'\n            }\n        }\n    },\n    {\n        id: 'house-11',\n        house: 11,\n        aliases: {\n            ru: [\n                'одиннадцатый дом',\n                '11 дом'\n            ],\n            en: [\n                'eleventh house',\n                '11th house',\n                'house 11'\n            ]\n        },\n        keywords: {\n            ru: [\n                'друзья',\n                'группы',\n                'сообщество',\n                'общие планы'\n            ],\n            en: [\n                'friends',\n                'groups',\n                'community',\n                'shared plans'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Одиннадцатый дом',\n                summary: 'Одиннадцатый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают друзей, группы, сообщества и цели, которые требуют совместной работы.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К одиннадцатому дому относят дружеские связи, участие в коллективах, профессиональные сообщества и общие планы. Речь идёт не о любых знакомых, а о людях, с которыми объединяют интересы или долгие цели.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается одиннадцатый дом, описывает способ входить в группу и выбирать круг общения. Планеты внутри дома и их аспекты с другими планетами добавляют детали к вопросам дружбы и совместной работы.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Одиннадцатый дом используют для чтения дружеских связей, участия в сообществах и целей, которые люди создают вместе.'\n            },\n            en: {\n                title: 'Eleventh house',\n                summary: 'The eleventh house is associated with friends, groups, communities, and shared plans.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It describes participation in a collective, friendships, professional networks, and goals that require cooperation among many people.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'The sign and planets in the eleventh house refine how a person chooses a social circle and takes part in shared work.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The eleventh house is about friends, communities, and goals built together.'\n            }\n        }\n    },\n    {\n        id: 'house-12',\n        house: 12,\n        aliases: {\n            ru: [\n                'двенадцатый дом',\n                '12 дом'\n            ],\n            en: [\n                'twelfth house',\n                '12th house',\n                'house 12'\n            ]\n        },\n        keywords: {\n            ru: [\n                'уединение',\n                'закрытые места',\n                'завершение',\n                'дела за кулисами'\n            ],\n            en: [\n                'solitude',\n                'closed institutions',\n                'closure',\n                'behind the scenes'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Двенадцатый дом',\n                summary: 'Двенадцатый дом — одна из двенадцати частей круга натальной карты. По нему рассматривают уединение, завершение дел, закрытые учреждения и работу вне публичного внимания.',\n                sections: [\n                    {\n                        title: 'Какие вопросы к нему относят',\n                        paragraphs: [\n                            'К двенадцатому дому относят добровольное уединение, вынужденную изоляцию, больницы и другие закрытые учреждения, непубличную работу и завершение затянувшихся дел. Эти темы рассматривают отдельно и не сводят к одному значению.'\n                        ]\n                    },\n                    {\n                        title: 'Что уточняет положение',\n                        paragraphs: [\n                            'Знак зодиака, в котором начинается двенадцатый дом, планеты внутри него и их аспекты с другими планетами уточняют отношение к тишине, ограничениям и делам без публичного признания. Этот дом не означает неизбежные тайны, одиночество или несчастье.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Двенадцатый дом используют для чтения уединения, завершения дел, закрытых учреждений и работы вне публичного внимания; несчастье он не предсказывает.'\n            },\n            en: {\n                title: 'Twelfth house',\n                summary: 'The twelfth house is associated with solitude, closure, institutions, and work outside public attention.',\n                sections: [\n                    {\n                        title: 'What this house covers',\n                        paragraphs: [\n                            'It includes the need to step away from outside noise, work behind the scenes, periods of isolation, and what ends before a new cycle.'\n                        ]\n                    },\n                    {\n                        title: 'How to read it',\n                        paragraphs: [\n                            'This house does not mean inevitable secrets or misfortune. Its sign and planets refine an approach to quiet, limits, and non-public work.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'The twelfth house is about solitude, closure, and what happens outside public attention.'\n            }\n        }\n    }\n];\nconst INDIVIDUAL_HOUSE_TOPICS = HOUSE_DEFINITIONS.map((definition)=>({\n        id: definition.id,\n        category: 'houses',\n        aliases: definition.aliases,\n        keywords: definition.keywords,\n        copy: definition.copy,\n        relatedTopicIds: [\n            'houses-overview',\n            'sign-vs-house',\n            'birth-time-and-houses'\n        ]\n    }));\nconst HOUSE_TOPICS = [\n    {\n        id: 'houses-overview',\n        category: 'houses',\n        aliases: {\n            ru: [\n                'дома натальной карты',\n                'астрологические дома',\n                'что такое дома'\n            ],\n            en: [\n                'natal houses',\n                'astrological houses',\n                'what houses mean'\n            ]\n        },\n        keywords: {\n            ru: [\n                'двенадцать домов',\n                'области жизни',\n                'куспиды'\n            ],\n            en: [\n                'twelve houses',\n                'areas of life',\n                'cusps'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Что такое дома',\n                summary: 'Дома — двенадцать секторов астрологической карты, построенных относительно конкретного места и времени. Они образуют отдельную сетку поверх зодиакального круга и не являются небесными телами.',\n                sections: [\n                    {\n                        title: 'Что такое сектор карты',\n                        kind: 'definition',\n                        paragraphs: [\n                            'Представьте круг, разделённый двенадцатью границами. Каждый участок между двумя границами — дом. Начальную границу называют куспидом. Номер дома показывает его место в порядке от первого до двенадцатого.'\n                        ]\n                    },\n                    {\n                        title: 'Почему домов двенадцать',\n                        kind: 'history',\n                        paragraphs: [\n                            'Двенадцать домов — правило сложившейся астрологической традиции. Их не находят телескопом и не выводят из двенадцати знаков простым наложением: это отдельное деление карты с собственной историей и методами расчёта.'\n                        ]\n                    },\n                    {\n                        title: 'Почему нужны время и место',\n                        kind: 'mechanism',\n                        paragraphs: [\n                            'Сетка домов опирается на местный горизонт и суточное вращение Земли. Один и тот же момент выглядит по-разному из Москвы и Владивостока, а через несколько минут границы уже сдвигаются. Поэтому без времени и места дома нельзя вычислить надёжно.'\n                        ]\n                    },\n                    {\n                        title: 'Почему системы домов отличаются',\n                        kind: 'calculation',\n                        paragraphs: [\n                            'Плацидус делит суточное движение точек неба по времени, целые знаки назначают первым домом весь знак Асцендента, равнодомная система строит двенадцать равных секторов. Из-за разных правил куспиды и дома некоторых планет могут не совпасть.'\n                        ]\n                    },\n                    {\n                        title: 'Зачем дома используют в астрологии',\n                        kind: 'astrology',\n                        paragraphs: [\n                            'Планету читают как функцию, знак — как способ её выражения, а дом — как группу вопросов, где эта функция рассматривается. Первый дом связывают с началом действия и самопроявлением, седьмой — с отношениями один на один, десятый — с публичной ролью и направлением деятельности.'\n                        ]\n                    },\n                    {\n                        title: 'Часто путают',\n                        kind: 'confusion',\n                        paragraphs: [\n                            'Первый дом не равен Овну, второй — Тельцу и так далее. Знаки всегда занимают равные участки зодиака, а дома зависят от времени, места и выбранной системы. Куспид — граница дома, а не «смесь» двух соседних домов.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Дома — расчётные сектора карты. Они отвечают на вопрос «в какой области» астрологи читают планету, и для них нужны время, место и выбранная система домов.'\n            },\n            en: {\n                title: 'What houses show',\n                summary: 'The twelve houses divide a chart into areas of life calculated for a specific time and place.',\n                sections: [\n                    {\n                        title: 'A house answers “where”',\n                        paragraphs: [\n                            'A planet describes a function, a sign its manner, and a house the area of life where that factor is especially relevant in chart reading.'\n                        ]\n                    },\n                    {\n                        title: 'Houses depend on input',\n                        paragraphs: [\n                            'The house grid is calculated from birth time and place. When time is unknown, it cannot be used as a precise personal part of the chart.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Houses describe areas of life and require a reliable birth time.'\n            }\n        },\n        relatedTopicIds: [\n            'house-cusp',\n            'house-systems',\n            'birth-time-and-houses',\n            'ascendant',\n            'sign-vs-house',\n            'house-1'\n        ],\n        diagram: 'houses',\n        sourceIds: [\n            'swiss-ephemeris-houses'\n        ]\n    },\n    {\n        id: 'sign-vs-house',\n        category: 'houses',\n        aliases: {\n            ru: [\n                'знак или дом',\n                'разница знака и дома',\n                'знаки и дома'\n            ],\n            en: [\n                'sign or house',\n                'sign versus house',\n                'signs and houses'\n            ]\n        },\n        keywords: {\n            ru: [\n                'как и где',\n                'планета в знаке',\n                'планета в доме'\n            ],\n            en: [\n                'how and where',\n                'planet in sign',\n                'planet in house'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Чем знак отличается от дома',\n                summary: 'Знак — один из двенадцати участков зодиака, а дом — одна из двенадцати частей круга натальной карты. Знак описывает, как выражается значение планеты, а дом указывает на связанные с ним жизненные вопросы.',\n                sections: [\n                    {\n                        title: 'Как это работает на примере',\n                        paragraphs: [\n                            'Марс в астрологии связывают с действием. Знак Марса описывает манеру действовать, а дом показывает, в каких жизненных вопросах это действие рассматривают. Для вывода нужны оба слоя, но они отвечают на разные вопросы.'\n                        ]\n                    },\n                    {\n                        title: 'Почему их нельзя приравнивать',\n                        paragraphs: [\n                            'Первый дом не равен Овну, второй дом не равен Тельцу и так далее. Зодиак заранее разделён на двенадцать равных знаков, а дома строятся по местному горизонту для времени и места рождения.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Знак зодиака описывает, как выражается значение планеты, а дом указывает, с какими жизненными вопросами его связывают при чтении карты.'\n            },\n            en: {\n                title: 'How a sign differs from a house',\n                summary: 'A sign describes a manner of action, while a house describes an area of life.',\n                sections: [\n                    {\n                        title: 'Two different layers',\n                        paragraphs: [\n                            'Mars, for example, is associated with action. Its sign refines the manner of action, while its house identifies the area where that topic matters most.'\n                        ]\n                    },\n                    {\n                        title: 'Do not substitute one for the other',\n                        paragraphs: [\n                            'The first house is not the same as Aries, the second is not Taurus, and so on. Houses and signs have separate meanings and different calculation bases.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'A sign answers “how”; a house answers “in which area of life”.'\n            }\n        },\n        relatedTopicIds: [\n            'houses-overview',\n            'planet-in-sign',\n            'how-to-read-natal-chart'\n        ]\n    },\n    {\n        id: 'birth-time-and-houses',\n        category: 'houses',\n        aliases: {\n            ru: [\n                'время рождения и дома',\n                'дома без времени',\n                'точность домов'\n            ],\n            en: [\n                'birth time and houses',\n                'houses without birth time',\n                'house accuracy'\n            ]\n        },\n        keywords: {\n            ru: [\n                'точное время',\n                'место рождения',\n                'куспиды',\n                'неизвестное время'\n            ],\n            en: [\n                'exact time',\n                'birth place',\n                'cusps',\n                'unknown time'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Почему домам нужно точное время',\n                summary: 'Сетка домов — деление круга натальной карты на двенадцать частей. Её строят от местного горизонта, поэтому для расчёта нужны время и место рождения.',\n                sections: [\n                    {\n                        title: 'Как возникает сетка домов',\n                        paragraphs: [\n                            'Время и географические координаты задают местный горизонт и углы карты. От них рассчитывают границы домов, а затем определяют, в какой дом попадает каждая планета. Даже небольшая ошибка во времени может сдвинуть эти границы.'\n                        ]\n                    },\n                    {\n                        title: 'Если время неизвестно',\n                        paragraphs: [\n                            'Случайную или условно выбранную сетку нельзя выдавать за личный расчёт. Без надёжного времени остаются доступными положения планет в знаках и аспекты между планетами, а дома в таком чтении не используют.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Дома зависят от местного горизонта, поэтому без надёжного времени и места рождения их нельзя считать точной личной частью карты.'\n            },\n            en: {\n                title: 'Why houses need an accurate time',\n                summary: 'Houses are built from the local horizon, so they depend on birth time and place.',\n                sections: [\n                    {\n                        title: 'How the grid is built',\n                        paragraphs: [\n                            'Time and geographic coordinates determine chart angles and house cusps. Those boundaries place planets into the twelve houses.'\n                        ]\n                    },\n                    {\n                        title: 'When time is unknown',\n                        paragraphs: [\n                            'A random house grid should not be presented as personal. It is better to read reliable planetary positions and aspects without houses.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Without an accurate birth time, houses cannot be treated as a reliable personal part of the chart.'\n            }\n        },\n        relatedTopicIds: [\n            'houses-overview',\n            'birth-time-in-chart',\n            'unknown-birth-time'\n        ]\n    },\n    ...INDIVIDUAL_HOUSE_TOPICS\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(pages-dir-node)/./lib/knowledge/houses.ts\n");

