eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   SIGN_TOPICS: () => (/* binding */ SIGN_TOPICS)\n/* harmony export */ });\nconst SIGN_DEFINITIONS = [\n    {\n        id: 'sign-aries',\n        sign: 'Aries',\n        aliases: {\n            ru: [\n                'овен',\n                'знак овна'\n            ],\n            en: [\n                'aries',\n                'ram'\n            ]\n        },\n        keywords: {\n            ru: [\n                'огонь',\n                'кардинальный',\n                'начало',\n                'прямота'\n            ],\n            en: [\n                'fire',\n                'cardinal',\n                'initiative',\n                'directness'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Овен',\n                summary: 'Овен — один из двенадцати знаков зодиака. В астрологии его связывают с быстрым началом, прямым действием и самостоятельностью.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Когда планета находится в Овне, её значение связывают с готовностью быстро включиться в дело и проверить решение действием. Конкретный смысл зависит от планеты: например, для Меркурия речь идёт о способе думать и говорить, а для Марса — о способе добиваться своего.'\n                        ]\n                    },\n                    {\n                        title: 'Не только напор',\n                        paragraphs: [\n                            'Овен не делает человека обязательно резким или конфликтным. Этот знак также связывают с ясной инициативой, самостоятельностью и готовностью первым начать действие.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Овен — знак зодиака, который в астрологии описывает прямой способ начинать дела, действовать самостоятельно и делать первый шаг.'\n            },\n            en: {\n                title: 'Aries',\n                summary: 'A cardinal fire sign associated with beginnings, direct action, and independence.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Aries describes a way of entering a task quickly, testing a decision through action, and moving without lengthy approval.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'It does not automatically mean conflict. In a calm form, the same sign supports clear initiative and a willingness to take the first step.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Aries is about beginnings, direct action, and moving first.'\n            }\n        }\n    },\n    {\n        id: 'sign-taurus',\n        sign: 'Taurus',\n        aliases: {\n            ru: [\n                'телец',\n                'знак тельца'\n            ],\n            en: [\n                'taurus',\n                'bull'\n            ]\n        },\n        keywords: {\n            ru: [\n                'земля',\n                'фиксированный',\n                'устойчивость',\n                'осязаемое'\n            ],\n            en: [\n                'earth',\n                'fixed',\n                'stability',\n                'tangible'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Телец',\n                summary: 'Телец — знак зодиака, который в астрологии связывают с устойчивым темпом, сохранением достигнутого и практическим результатом.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Тельце обычно описывает неторопливый способ действовать, опору на привычный порядок и желание получить результат, который можно сохранить или использовать на практике.'\n                        ]\n                    },\n                    {\n                        title: 'Не только медлительность',\n                        paragraphs: [\n                            'Телец не означает пассивность. Когда цель понятна, устойчивый темп помогает действовать терпеливо, последовательно и долго продолжать начатое.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Телец — знак зодиака, который описывает устойчивый темп, внимание к практической стороне дела и стремление сохранить достигнутое.'\n            },\n            en: {\n                title: 'Taurus',\n                summary: 'A fixed earth sign associated with steady pace, preservation, and tangible results.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Taurus describes a way of moving without unnecessary haste, consolidating what has been achieved, and choosing what can last.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Stability is not passivity. This sign can act with persistence when the goal is clear and practically meaningful.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Taurus is about stability, preservation, and dependable results.'\n            }\n        }\n    },\n    {\n        id: 'sign-gemini',\n        sign: 'Gemini',\n        aliases: {\n            ru: [\n                'близнецы',\n                'знак близнецов'\n            ],\n            en: [\n                'gemini',\n                'twins'\n            ]\n        },\n        keywords: {\n            ru: [\n                'воздух',\n                'мутабельный',\n                'информация',\n                'сравнение'\n            ],\n            en: [\n                'air',\n                'mutable',\n                'information',\n                'comparison'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Близнецы',\n                summary: 'Близнецы — знак зодиака, который в астрологии связывают с вопросами, обменом сведениями и сравнением разных точек зрения.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Близнецах обычно описывает подвижный способ работать с информацией: замечать несколько вариантов, связывать факты и уточнять мысль в разговоре.'\n                        ]\n                    },\n                    {\n                        title: 'Не только переменчивость',\n                        paragraphs: [\n                            'Близнецы не означают, что человек всегда непостоянен. Смена мнения может быть реакцией на новые сведения, а интерес к разным версиям помогает точнее понять вопрос.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Близнецы — знак зодиака, который описывает подвижное мышление, обмен информацией и привычку сравнивать несколько вариантов.'\n            },\n            en: {\n                title: 'Gemini',\n                summary: 'A mutable air sign associated with questions, information exchange, and changing perspective.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Gemini describes a way of noticing several options, connecting facts quickly, and refining a thought through conversation.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Changing an opinion does not always mean inconsistency. It can be an honest response to new information or a more accurate wording.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Gemini is about information, comparison, and flexible thought.'\n            }\n        }\n    },\n    {\n        id: 'sign-cancer',\n        sign: 'Cancer',\n        aliases: {\n            ru: [\n                'рак',\n                'знак рака'\n            ],\n            en: [\n                'cancer',\n                'crab'\n            ]\n        },\n        keywords: {\n            ru: [\n                'вода',\n                'кардинальный',\n                'близость',\n                'безопасность'\n            ],\n            en: [\n                'water',\n                'cardinal',\n                'closeness',\n                'security'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Рак',\n                summary: 'Рак — знак зодиака, который в астрологии связывают с близостью, заботой, памятью и защитой того, что человек считает своим.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Раке обычно описывает внимание к доверию, знакомой обстановке и чувствам близких людей. Перед открытым действием здесь часто важно понять, можно ли чувствовать себя спокойно и безопасно.'\n                        ]\n                    },\n                    {\n                        title: 'Не только мягкость',\n                        paragraphs: [\n                            'Рак не означает слабость или постоянную уступчивость. Когда нужно защитить близкого человека, дом или личные границы, с этим знаком связывают твёрдые и решительные действия.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Рак — знак зодиака, который описывает заботу о близких, потребность в доверии и защиту привычного личного пространства.'\n            },\n            en: {\n                title: 'Cancer',\n                summary: 'A cardinal water sign associated with closeness, protection, and a sense of belonging.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Cancer describes a way of looking for trust, memory, and emotional safety before opening up or making a decision.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Care does not mean constant softness. When protecting what matters, this sign can be decisive and set clear boundaries.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Cancer is about closeness, protection, and what a person considers their own.'\n            }\n        }\n    },\n    {\n        id: 'sign-leo',\n        sign: 'Leo',\n        aliases: {\n            ru: [\n                'лев',\n                'знак льва'\n            ],\n            en: [\n                'leo',\n                'lion'\n            ]\n        },\n        keywords: {\n            ru: [\n                'огонь',\n                'фиксированный',\n                'самовыражение',\n                'личная позиция'\n            ],\n            en: [\n                'fire',\n                'fixed',\n                'self-expression',\n                'personal expression'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Лев',\n                summary: 'Лев — знак зодиака, который в астрологии связывают с заметным самовыражением, личной позицией и гордостью за созданное.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты во Льве обычно описывает желание выразить личное отношение, сделать результат узнаваемым и не прятать собственный вклад.'\n                        ]\n                    },\n                    {\n                        title: 'Не только внимание',\n                        paragraphs: [\n                            'Лев не означает постоянное стремление быть в центре. Этот знак также связывают с готовностью отвечать за сделанное, поддерживать других и открыто обозначать свою позицию.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Лев — знак зодиака, который описывает заметное самовыражение, личное отношение к делу и готовность отвечать за свой результат.'\n            },\n            en: {\n                title: 'Leo',\n                summary: 'A fixed fire sign associated with authorship, visibility, and loyalty to one’s chosen expression.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Leo describes a way of putting a personal stamp on a task, taking a visible place, and standing behind what is created in one’s name.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Visibility does not always mean seeking the center of attention. It can also mean stating a position clearly and encouraging others.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Leo is about authorship, visible expression, and personal responsibility for the result.'\n            }\n        }\n    },\n    {\n        id: 'sign-virgo',\n        sign: 'Virgo',\n        aliases: {\n            ru: [\n                'дева',\n                'знак девы'\n            ],\n            en: [\n                'virgo',\n                'maiden'\n            ]\n        },\n        keywords: {\n            ru: [\n                'земля',\n                'мутабельный',\n                'детали',\n                'порядок'\n            ],\n            en: [\n                'earth',\n                'mutable',\n                'detail',\n                'order'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Дева',\n                summary: 'Дева — знак зодиака, который в астрологии связывают с точностью, вниманием к деталям и практической полезностью.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Деве обычно описывает привычку разбирать задачу на части, проверять детали и исправлять то, что мешает работе или точному результату.'\n                        ]\n                    },\n                    {\n                        title: 'Не только критика',\n                        paragraphs: [\n                            'Дева не означает постоянную придирчивость. Внимание к мелочам может помогать отличить существенную ошибку от неважной и сделать работу понятнее.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Дева — знак зодиака, который описывает точный подход к задаче, проверку деталей и стремление сделать результат полезным на практике.'\n            },\n            en: {\n                title: 'Virgo',\n                summary: 'A mutable earth sign associated with precision, usefulness, and refining a working order.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Virgo describes a way of breaking a task into parts, noticing mismatches, and improving something that needs to work in practice.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Attention to detail does not have to become fault-finding. It can separate an important error from an irrelevant imperfection.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Virgo is about precision, order, and practical usefulness.'\n            }\n        }\n    },\n    {\n        id: 'sign-libra',\n        sign: 'Libra',\n        aliases: {\n            ru: [\n                'весы',\n                'знак весов'\n            ],\n            en: [\n                'libra',\n                'scales'\n            ]\n        },\n        keywords: {\n            ru: [\n                'воздух',\n                'кардинальный',\n                'равновесие',\n                'договорённость'\n            ],\n            en: [\n                'air',\n                'cardinal',\n                'balance',\n                'agreement'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Весы',\n                summary: 'Весы — знак зодиака, который в астрологии связывают со сравнением позиций, взаимностью и поиском понятной договорённости.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Весах обычно описывает привычку учитывать другую сторону, сравнивать варианты и искать решение, правила которого понятны всем участникам.'\n                        ]\n                    },\n                    {\n                        title: 'Не только сомнения',\n                        paragraphs: [\n                            'Весы не означают неспособность принять решение. Дополнительное сравнение может быть способом увидеть последствия для обеих сторон и выбрать более справедливую меру.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Весы — знак зодиака, который описывает сравнение разных позиций, внимание к взаимности и стремление договориться на понятных условиях.'\n            },\n            en: {\n                title: 'Libra',\n                summary: 'A cardinal air sign associated with comparing positions, reciprocity, and agreement.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Libra describes a way of considering the other side, looking for a fair measure, and shaping a decision that all participants can understand.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Comparing options does not always mean indecision. It can be a way of seeing the consequences for everyone involved.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Libra is about comparing positions, reciprocity, and clear agreements.'\n            }\n        }\n    },\n    {\n        id: 'sign-scorpio',\n        sign: 'Scorpio',\n        aliases: {\n            ru: [\n                'скорпион',\n                'знак скорпиона'\n            ],\n            en: [\n                'scorpio',\n                'scorpion'\n            ]\n        },\n        keywords: {\n            ru: [\n                'вода',\n                'фиксированный',\n                'доверие',\n                'глубина'\n            ],\n            en: [\n                'water',\n                'fixed',\n                'trust',\n                'depth'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Скорпион',\n                summary: 'Скорпион — знак зодиака, который в астрологии связывают с доверием, личными тайнами и вниманием к сложным переменам.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Скорпионе обычно описывает стремление дойти до причины, осторожно выбирать степень близости и не раскрывать важную информацию без доверия.'\n                        ]\n                    },\n                    {\n                        title: 'Не только драма',\n                        paragraphs: [\n                            'Скорпион не означает постоянный кризис, ревность или манипуляцию. Этот знак также связывают с выдержкой и способностью долго разбираться в трудной теме.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Скорпион — знак зодиака, который описывает осторожное доверие, внимание к скрытым причинам и выдержку перед сложными переменами.'\n            },\n            en: {\n                title: 'Scorpio',\n                summary: 'A fixed water sign associated with trust, private information, and deep change.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Scorpio describes a way of looking beyond a surface answer, choosing closeness carefully, and keeping important matters private.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Depth does not mean constant drama. This sign is also associated with endurance and a calm ability to examine a difficult subject.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Scorpio is about trust, depth, and attention to what is not immediately visible.'\n            }\n        }\n    },\n    {\n        id: 'sign-sagittarius',\n        sign: 'Sagittarius',\n        aliases: {\n            ru: [\n                'стрелец',\n                'знак стрельца'\n            ],\n            en: [\n                'sagittarius',\n                'archer'\n            ]\n        },\n        keywords: {\n            ru: [\n                'огонь',\n                'мутабельный',\n                'смысл',\n                'горизонт'\n            ],\n            en: [\n                'fire',\n                'mutable',\n                'meaning',\n                'horizon'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Стрелец',\n                summary: 'Стрелец — знак зодиака, который в астрологии связывают с поиском смысла, обучением и стремлением увидеть общую картину.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Стрельце обычно описывает стремление связать отдельные факты с более широкой идеей, учиться через опыт и выходить за пределы уже знакомого.'\n                        ]\n                    },\n                    {\n                        title: 'Не только широкие идеи',\n                        paragraphs: [\n                            'Стрелец не гарантирует правильный ответ и не заменяет проверку фактов. Общая идея становится убедительнее, когда учитывает конкретные обстоятельства и возможные исключения.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Стрелец — знак зодиака, который описывает поиск смысла, интерес к обучению и стремление связать факты в общую картину.'\n            },\n            en: {\n                title: 'Sagittarius',\n                summary: 'A mutable fire sign associated with meaning, broader horizons, and the larger picture.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Sagittarius describes a way of connecting facts to a wider idea, learning through experience, and looking beyond familiar surroundings.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'A broad view does not replace accuracy. A persuasive idea still needs checked facts and attention to the specific situation.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Sagittarius is about meaning, learning, and widening the known horizon.'\n            }\n        }\n    },\n    {\n        id: 'sign-capricorn',\n        sign: 'Capricorn',\n        aliases: {\n            ru: [\n                'козерог',\n                'знак козерога'\n            ],\n            en: [\n                'capricorn',\n                'sea goat'\n            ]\n        },\n        keywords: {\n            ru: [\n                'земля',\n                'кардинальный',\n                'структура',\n                'ответственность'\n            ],\n            en: [\n                'earth',\n                'cardinal',\n                'structure',\n                'responsibility'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Козерог',\n                summary: 'Козерог — знак зодиака, который в астрологии связывают с порядком действий, ответственностью и результатом, требующим времени.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Козероге обычно описывает стремление понять требования задачи, выстроить последовательность шагов и учитывать последствия в долгой перспективе.'\n                        ]\n                    },\n                    {\n                        title: 'Не только строгость',\n                        paragraphs: [\n                            'Козерог не означает холодность или отсутствие юмора. Основная тема этого знака связана с готовностью принять ограничения и отвечать за выбранное решение.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Козерог — знак зодиака, который описывает последовательный подход, ответственность за решение и работу ради результата, требующего времени.'\n            },\n            en: {\n                title: 'Capricorn',\n                summary: 'A cardinal earth sign associated with structure, responsibility, and long-term results.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Capricorn describes a way of seeing a task’s requirements, arranging the steps, and considering consequences over the long term.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Seriousness does not rule out flexibility or humor. The central point is a willingness to take responsibility for a chosen decision.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Capricorn is about structure, responsibility, and results that take time.'\n            }\n        }\n    },\n    {\n        id: 'sign-aquarius',\n        sign: 'Aquarius',\n        aliases: {\n            ru: [\n                'водолей',\n                'знак водолея'\n            ],\n            en: [\n                'aquarius',\n                'water bearer'\n            ]\n        },\n        keywords: {\n            ru: [\n                'воздух',\n                'фиксированный',\n                'система',\n                'независимость'\n            ],\n            en: [\n                'air',\n                'fixed',\n                'system',\n                'independence'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Водолей',\n                summary: 'Водолей — знак зодиака, который в астрологии связывают с независимым взглядом, общими правилами и устройством групп.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Водолее обычно описывает привычку смотреть на правила со стороны, замечать, как устроена система, и сохранять собственное мнение внутри группы.'\n                        ]\n                    },\n                    {\n                        title: 'Не только отстранённость',\n                        paragraphs: [\n                            'Водолей не означает безразличие к людям. Независимая позиция может сочетаться с интересом к справедливым общим правилам и равным возможностям для участников группы.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Водолей — знак зодиака, который описывает независимый взгляд на правила, внимание к устройству системы и отношениям человека с группой.'\n            },\n            en: {\n                title: 'Aquarius',\n                summary: 'A fixed air sign associated with systems thinking, independence, and how groups are organized.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Aquarius describes a way of viewing rules from the outside, noticing how the whole works, and keeping an independent position within a group.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Independence does not mean indifference to people. This sign often focuses on shared rules and equal access.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Aquarius is about an independent view, systems, and a person’s relationship with a group.'\n            }\n        }\n    },\n    {\n        id: 'sign-pisces',\n        sign: 'Pisces',\n        aliases: {\n            ru: [\n                'рыбы',\n                'знак рыб'\n            ],\n            en: [\n                'pisces',\n                'fish'\n            ]\n        },\n        keywords: {\n            ru: [\n                'вода',\n                'мутабельный',\n                'восприимчивость',\n                'воображение'\n            ],\n            en: [\n                'water',\n                'mutable',\n                'receptivity',\n                'imagination'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Рыбы',\n                summary: 'Рыбы — знак зодиака, который в астрологии связывают с восприимчивостью к настроению, воображением и образным мышлением.',\n                sections: [\n                    {\n                        title: 'Как читают этот знак',\n                        paragraphs: [\n                            'Положение планеты в Рыбах обычно описывает способность замечать общий тон происходящего, связывать разрозненные впечатления и выражать мысль через образы.'\n                        ]\n                    },\n                    {\n                        title: 'Не только чувствительность',\n                        paragraphs: [\n                            'Рыбы не означают беспомощность или отсутствие границ. Этот знак говорит о восприимчивости, а способность отличать собственные чувства от чужих зависит не от одного положения карты.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Рыбы — знак зодиака, который описывает восприимчивость к настроению, воображение и способность связывать разные впечатления в один образ.'\n            },\n            en: {\n                title: 'Pisces',\n                summary: 'A mutable water sign associated with receptivity, imagination, and porous boundaries between impressions.',\n                sections: [\n                    {\n                        title: 'Main theme',\n                        paragraphs: [\n                            'Pisces describes a way of sensing the overall tone, connecting scattered impressions, and thinking through images as well as direct statements.'\n                        ]\n                    },\n                    {\n                        title: 'Keep in mind',\n                        paragraphs: [\n                            'Sensitivity does not remove the need for clear boundaries. Without them, it becomes harder to distinguish one’s own state from someone else’s.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Pisces is about receptivity, imagination, and connections between different impressions.'\n            }\n        }\n    }\n];\nconst INDIVIDUAL_SIGN_TOPICS = SIGN_DEFINITIONS.map((definition)=>({\n        id: definition.id,\n        category: 'signs',\n        aliases: definition.aliases,\n        keywords: definition.keywords,\n        copy: definition.copy,\n        relatedTopicIds: [\n            'signs-overview',\n            'sign-elements',\n            'sign-modalities'\n        ]\n    }));\nconst SIGN_TOPICS = [\n    {\n        id: 'signs-overview',\n        category: 'signs',\n        aliases: {\n            ru: [\n                'знаки зодиака',\n                'зодиак',\n                'что такое знак'\n            ],\n            en: [\n                'zodiac signs',\n                'zodiac',\n                'what is a sign'\n            ]\n        },\n        keywords: {\n            ru: [\n                'двенадцать знаков',\n                'стиль',\n                'положение планеты'\n            ],\n            en: [\n                'twelve signs',\n                'style',\n                'planetary placement'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Что описывают знаки',\n                summary: 'Знак зодиака — это один из двенадцати равных участков круга, в котором при расчёте карты находится планета или важная точка.',\n                sections: [\n                    {\n                        title: 'Что значит «планета в знаке»',\n                        paragraphs: [\n                            'Расчёт показывает, в каком участке зодиакального круга находилась каждая планета. В астрологии планета задаёт тему, а знак описывает привычный способ её выражать. Поэтому Овен у Меркурия относится к мышлению и речи, а Овен у Марса — к способу действовать и добиваться своего.'\n                        ]\n                    },\n                    {\n                        title: 'Почему знак не равен человеку',\n                        paragraphs: [\n                            'В одной натальной карте планеты обычно находятся в разных знаках. К их значениям добавляют дома и аспекты, то есть области карты и углы между планетами. Поэтому ни солнечный знак, ни любой другой знак не описывает личность целиком.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Знак зодиака показывает, в каком из двенадцати участков зодиакального круга находится планета; в астрологии по знаку описывают, как выражается её значение.'\n            },\n            en: {\n                title: 'What signs describe',\n                summary: 'A sign shows the manner in which a planet or key chart point operates.',\n                sections: [\n                    {\n                        title: 'A sign answers “how”',\n                        paragraphs: [\n                            'A planet names a function, while a sign describes its familiar manner. The same sign therefore reads differently for the Sun, Moon, or Mars.'\n                        ]\n                    },\n                    {\n                        title: 'A sign is not the whole person',\n                        paragraphs: [\n                            'No single sign describes an entire personality. Different planets, houses, and aspects work together in the chart.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'A sign is the manner of a particular planet, not a complete description of a person.'\n            }\n        },\n        relatedTopicIds: [\n            'sign-elements',\n            'sign-modalities',\n            'planet-in-sign'\n        ],\n        diagram: 'zodiac-wheel'\n    },\n    ...INDIVIDUAL_SIGN_TOPICS,\n    {\n        id: 'sign-elements',\n        category: 'signs',\n        aliases: {\n            ru: [\n                'стихии знаков',\n                'огонь земля воздух вода'\n            ],\n            en: [\n                'sign elements',\n                'fire earth air water'\n            ]\n        },\n        keywords: {\n            ru: [\n                'огненные знаки',\n                'земные знаки',\n                'воздушные знаки',\n                'водные знаки'\n            ],\n            en: [\n                'fire signs',\n                'earth signs',\n                'air signs',\n                'water signs'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Четыре стихии знаков',\n                summary: 'Стихии знаков — это четыре астрологические группы: Огонь, Земля, Воздух и Вода. Они не обозначают физические вещества, а объединяют знаки с похожим способом действовать и воспринимать происходящее.',\n                sections: [\n                    {\n                        title: 'Огонь и Земля',\n                        paragraphs: [\n                            'К Огню относят Овен, Лев и Стрелец; эту группу связывают с инициативой и прямым выражением. К Земле относят Телец, Деву и Козерог; её связывают с практическими задачами, устойчивостью и результатом, который можно проверить.'\n                        ]\n                    },\n                    {\n                        title: 'Воздух и Вода',\n                        paragraphs: [\n                            'К Воздуху относят Близнецы, Весы и Водолей; эту группу связывают с мыслями, словами и обменом между людьми. К Воде относят Рак, Скорпион и Рыбы; её связывают с чувствами, близостью и восприимчивостью к настроению.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Стихия — это группа знаков с общей темой: Огонь связывают с инициативой, Землю с практикой, Воздух с обменом мыслями, а Воду с чувствами и близостью.'\n            },\n            en: {\n                title: 'The four sign elements',\n                summary: 'Fire, Earth, Air, and Water group signs by a broad way of perceiving and acting.',\n                sections: [\n                    {\n                        title: 'Fire and Earth',\n                        paragraphs: [\n                            'Fire—Aries, Leo, and Sagittarius—is associated with initiative and direct expression. Earth—Taurus, Virgo, and Capricorn—is associated with practice, form, and verifiable results.'\n                        ]\n                    },\n                    {\n                        title: 'Air and Water',\n                        paragraphs: [\n                            'Air—Gemini, Libra, and Aquarius—is associated with thought, language, and connections between people. Water—Cancer, Scorpio, and Pisces—is associated with feeling, attachment, and receptivity.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'An element gives a sign its broad language: action, practice, thought, or feeling.'\n            }\n        },\n        relatedTopicIds: [\n            'signs-overview',\n            'sign-modalities',\n            'planet-in-sign'\n        ]\n    },\n    {\n        id: 'sign-modalities',\n        category: 'signs',\n        aliases: {\n            ru: [\n                'модальности знаков',\n                'кресты знаков',\n                'кардинальный фиксированный мутабельный'\n            ],\n            en: [\n                'sign modalities',\n                'qualities of signs',\n                'cardinal fixed mutable'\n            ]\n        },\n        keywords: {\n            ru: [\n                'кардинальные знаки',\n                'фиксированные знаки',\n                'мутабельные знаки'\n            ],\n            en: [\n                'cardinal signs',\n                'fixed signs',\n                'mutable signs'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Кардинальные, фиксированные и мутабельные знаки',\n                summary: 'Модальность — это деление знаков по тому, как они ведут дело во времени: начинают его, удерживают выбранное направление или приспосабливаются к переменам.',\n                sections: [\n                    {\n                        title: 'Кардинальные и фиксированные',\n                        paragraphs: [\n                            'Кардинальными называют Овен, Рак, Весы и Козерог: в астрологии их связывают с началом и заданием нового направления. Фиксированными называют Телец, Лев, Скорпион и Водолей: их связывают с продолжением дела и сохранением выбранного курса.'\n                        ]\n                    },\n                    {\n                        title: 'Мутабельные',\n                        paragraphs: [\n                            'Мутабельными называют Близнецы, Деву, Стрелец и Рыбы. Их связывают со сменой подхода, приспособлением к новым условиям и переходом от одного этапа к следующему.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Модальность делит знаки на три группы: кардинальные начинают новое, фиксированные удерживают направление, а мутабельные меняют подход под новые условия.'\n            },\n            en: {\n                title: 'Cardinal, fixed, and mutable signs',\n                summary: 'Modality shows how a sign begins, sustains, or changes a course of action.',\n                sections: [\n                    {\n                        title: 'Cardinal and fixed',\n                        paragraphs: [\n                            'Cardinal Aries, Cancer, Libra, and Capricorn set a new direction. Fixed Taurus, Leo, Scorpio, and Aquarius sustain and deepen a chosen course.'\n                        ]\n                    },\n                    {\n                        title: 'Mutable',\n                        paragraphs: [\n                            'Mutable Gemini, Virgo, Sagittarius, and Pisces adjust an approach to changing conditions and help move from one stage to another.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Cardinal signs begin, fixed signs sustain, and mutable signs adapt.'\n            }\n        },\n        relatedTopicIds: [\n            'signs-overview',\n            'sign-elements',\n            'planet-in-sign'\n        ]\n    },\n    {\n        id: 'planet-in-sign',\n        category: 'signs',\n        aliases: {\n            ru: [\n                'планета в знаке',\n                'что значит планета в знаке'\n            ],\n            en: [\n                'planet in a sign',\n                'what a planet in a sign means'\n            ]\n        },\n        keywords: {\n            ru: [\n                'планета',\n                'знак',\n                'значение',\n                'способ действия'\n            ],\n            en: [\n                'planet',\n                'sign',\n                'function',\n                'manner'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Как читать планету в знаке',\n                summary: 'Планета в знаке — это положение, которое показывает, в каком из двенадцати участков зодиакального круга находилась планета в момент рождения.',\n                sections: [\n                    {\n                        title: 'Что добавляет знак',\n                        paragraphs: [\n                            'В астрологии у каждой планеты есть своя тема, а знак уточняет способ её выражения. Например, Меркурий связывают с мышлением и речью, поэтому знак Меркурия описывает привычный способ собирать сведения и формулировать мысль.'\n                        ]\n                    },\n                    {\n                        title: 'Что ещё влияет на значение',\n                        paragraphs: [\n                            'Положение планеты читают вместе с домом, то есть областью карты, и аспектами, то есть углами к другим планетам. Поэтому одна и та же планета в одном знаке может получать разный дополнительный смысл в разных картах.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Планета в знаке показывает, какая астрологическая тема рассматривается и каким способом она выражается; полный вывод также учитывает дом и углы к другим планетам.'\n            },\n            en: {\n                title: 'How to read a planet in a sign',\n                summary: 'A planet names a function, while its sign describes the manner in which it operates.',\n                sections: [\n                    {\n                        title: 'Two different questions',\n                        paragraphs: [\n                            'For example, Mercury is associated with thought and speech, while its sign refines the familiar way of gathering information and wording an idea.'\n                        ]\n                    },\n                    {\n                        title: 'Not a standalone label',\n                        paragraphs: [\n                            'A planetary placement is read with its house and aspects. The same sign can work differently in different charts.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'First identify the planet’s function, then add the manner of its sign.'\n            }\n        },\n        relatedTopicIds: [\n            'signs-overview',\n            'sign-elements',\n            'how-to-read-natal-chart'\n        ]\n    },\n    {\n        id: 'zodiac-signs-vs-constellations',\n        category: 'signs',\n        aliases: {\n            ru: [\n                'знак и созвездие',\n                'зодиакальные созвездия'\n            ],\n            en: [\n                'sign versus constellation',\n                'zodiac constellations'\n            ]\n        },\n        keywords: {\n            ru: [\n                'зодиакальный круг',\n                'созвездия',\n                'тропический зодиак'\n            ],\n            en: [\n                'zodiac circle',\n                'constellations',\n                'tropical zodiac'\n            ]\n        },\n        copy: {\n            ru: {\n                title: 'Чем знак отличается от созвездия',\n                summary: 'Знак зодиака — это равный участок расчётного круга, а созвездие — область звёздного неба с границами, принятыми в астрономии.',\n                sections: [\n                    {\n                        title: 'Как устроены знаки',\n                        paragraphs: [\n                            'В тропической астрологии годовой путь Солнца по небу делят на двенадцать равных участков. Первый знак начинается в точке мартовского равноденствия, когда день и ночь имеют примерно равную продолжительность.'\n                        ]\n                    },\n                    {\n                        title: 'Как устроены созвездия',\n                        paragraphs: [\n                            'Созвездия занимают на небе области разного размера и имеют собственные астрономические границы. Знаки получили похожие названия по исторической связи с созвездиями, но сегодня это две разные системы.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Знаки зодиака — двенадцать равных участков расчётного круга, а созвездия — области звёздного неба разного размера; их названия связаны исторически, но это не одно и то же.'\n            },\n            en: {\n                title: 'A sign and a constellation are not the same',\n                summary: 'A sign is a section of the zodiac, while a constellation is an area of the starry sky.',\n                sections: [\n                    {\n                        title: 'Signs',\n                        paragraphs: [\n                            'In tropical astrology, the zodiac is divided into twelve equal signs beginning at the March equinox.'\n                        ]\n                    },\n                    {\n                        title: 'Constellations',\n                        paragraphs: [\n                            'Astronomical constellations vary in size and have their own boundaries. Their names are historically connected with the signs, but they are different coordinate systems.'\n                        ]\n                    }\n                ],\n                shortAnswer: 'Signs are equal sections of the zodiac; constellations are actual regions of the starry sky.'\n            }\n        },\n        relatedTopicIds: [\n            'signs-overview',\n            'sign-elements',\n            'what-chart-calculates'\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(pages-dir-node)/./lib/knowledge/signs.ts\n");

